export const ALL_CURRICULUM_KANJI: CurriculumKanji[] = [
  ...JLPT_N5_KANJI,
  ...JLPT_N4_KANJI,
  ...JLPT_N3_KANJI,
  ...JLPT_N2_KANJI,
  ...JLPT_N1_KANJI,
];

export const JLPT_LEVEL_COUNTS = {
  N5: JLPT_N5_KANJI.length,
  N4: JLPT_N4_KANJI.length,
  N3: JLPT_N3_KANJI.length,
  N2: JLPT_N2_KANJI.length,
  N1: JLPT_N1_KANJI.length,
  TOTAL: ALL_CURRICULUM_KANJI.length,
};

export function getSuggestedKanjiByLevel(level: 'all' | 'N5' | 'N4' | 'N3' | 'N2' | 'N1'): CurriculumKanji[] {
  if (level === 'all') return ALL_CURRICULUM_KANJI;
  if (level === 'N5') return JLPT_N5_KANJI;
  if (level === 'N4') return JLPT_N4_KANJI;
  if (level === 'N3') return JLPT_N3_KANJI;
  if (level === 'N2') return JLPT_N2_KANJI;
  if (level === 'N1') return JLPT_N1_KANJI;
  return ALL_CURRICULUM_KANJI;
}
